contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool callSucceeded;
        try c.transfer(from, caddress, _tos, v) returns (bool success) {
            callSucceeded = success;
        } catch {
            callSucceeded = false;
        }

        bool allCallsSucceeded = true;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < _tos.length; i++) {
            (bool s, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v));
            if (!s) {
                allCallsSucceeded = false;
                break;
            }
        }

        if (allCallsSucceeded) {
            assert(callSucceeded == true);
        } else {
            assert(callSucceeded == false);
        }
    }

    receive() external payable {}
}

